# Generated by palette from theme "{{ theme }}". Edits are overwritten on the next switch.
# Use from sketchybarrc and each plugin:
#   source "$HOME/.config/palette/current/sketchybar.sh"
# Colours are 0xAARRGGBB (alpha first).

export PALETTE_THEME="{{ theme }}"
export PALETTE_MODE="{{ mode }}"

# Semantic names
export ACCENT={{ accent | argb }}
export BACKGROUND={{ background | argb }}
export SURFACE={{ lighter_background | argb }}
export FOREGROUND={{ foreground | argb }}
export MUTED={{ muted | argb }}
export SELECTION={{ selection | argb }}

# Common SketchyBar names
export PILL={{ selection | argb("f0") }}
export FG={{ bright_foreground | argb }}
export GREY={{ dark_foreground | argb }}
export DARK={{ background | argb }}
export RED={{ red | argb }}
export ORANGE={{ orange | argb }}
export YELLOW={{ yellow | argb }}
export GREEN={{ green | argb }}
export CYAN={{ cyan | argb }}
export BLUE={{ blue | argb }}
export PURPLE={{ magenta | argb }}
export MAGENTA={{ magenta | argb }}

# Every theme colour by its theme name, for the bar Palette builds (Settings → Bar).
export C_accent={{ accent | argb }}
export C_selection={{ selection | argb }}
export C_muted={{ muted | argb }}
export C_background={{ background | argb }}
export C_dark_background={{ dark_background | argb }}
export C_darker_background={{ darker_background | argb }}
export C_lighter_background={{ lighter_background | argb }}
export C_foreground={{ foreground | argb }}
export C_dark_foreground={{ dark_foreground | argb }}
export C_light_foreground={{ light_foreground | argb }}
export C_bright_foreground={{ bright_foreground | argb }}
export C_red={{ red | argb }}
export C_yellow={{ yellow | argb }}
export C_green={{ green | argb }}
export C_cyan={{ cyan | argb }}
export C_blue={{ blue | argb }}
export C_magenta={{ magenta | argb }}
export C_orange={{ orange | argb }}
export C_brown={{ brown | argb }}
export C_bright_red={{ bright_red | argb }}
export C_bright_yellow={{ bright_yellow | argb }}
export C_bright_green={{ bright_green | argb }}
export C_bright_cyan={{ bright_cyan | argb }}
export C_bright_blue={{ bright_blue | argb }}
export C_bright_magenta={{ bright_magenta | argb }}
